// Auto-setup for BasementScene.fbx (generated by build_v2.py in Blender).
// - Imports the baked texture sets in Assets/BasementScene/Textures with the right settings
//   (normal maps as Normal Map, MetalSmooth as linear).
// - Turns every "M_<Group>" material from the FBX into a URP Lit material using
//   T_<Group>_Albedo / _Normal / _MetalSmooth / _Emission.
// - Makes M_Water and M_Glass transparent.
// Menu: Tools > Can You Hear Me > Reimport Basement   (use it if textures were missing on first import)
using System.Collections.Generic;
using System.IO;
using UnityEditor;
using UnityEngine;
using UnityEngine.Rendering;

public class BasementSceneImporter : AssetPostprocessor
{
    public const string FbxPath = "Assets/BasementScene.fbx";
    public const string TexDir = "Assets/BasementScene/Textures/";

    static readonly Dictionary<string, float> EmissionGain = new Dictionary<string, float>
    {
        { "Radio", 3f }, { "Keypad", 3f }, { "Table", 8f }, { "Ceiling", 8f }
    };

    bool IsBasement => assetPath == FbxPath;

    public const string VoidDoorsDir = "Assets/Resources/VoidDoors/";   // floating doors for DoorVoidEnding

    void OnPreprocessTexture()
    {
        if (!assetPath.StartsWith(TexDir) && !assetPath.StartsWith(VoidDoorsDir)) return;
        var ti = (TextureImporter)assetImporter;
        string n = Path.GetFileNameWithoutExtension(assetPath);
        if (n.EndsWith("_Normal")) ti.textureType = TextureImporterType.NormalMap;
        if (n.EndsWith("_MetalSmooth")) { ti.sRGBTexture = false; ti.alphaSource = TextureImporterAlphaSource.FromInput; }
        ti.maxTextureSize = 4096;
        ti.mipmapEnabled = true;
        ti.anisoLevel = 4;
    }

    void OnPreprocessModel()
    {
        if (assetPath.StartsWith(VoidDoorsDir))
        {
            // DoorVoidEnding combines these meshes at runtime, so they must stay readable (required in builds)
            var vm = (ModelImporter)assetImporter;
            vm.isReadable = true;
            vm.materialImportMode = ModelImporterMaterialImportMode.None;
            vm.bakeAxisConversion = true;
            vm.addCollider = false;
            vm.importCameras = false; vm.importLights = false;
            return;
        }
        if (!IsBasement) return;
        var mi = (ModelImporter)assetImporter;
        mi.materialImportMode = ModelImporterMaterialImportMode.ImportViaMaterialDescription;
        mi.materialLocation = ModelImporterMaterialLocation.InPrefab;
        mi.importCameras = false;
        mi.importLights = false;
        mi.useFileScale = true;
        mi.bakeAxisConversion = true;   // no -90 X rotation on the root objects
        mi.isReadable = false;
        mi.addCollider = true;          // floor/walls must be solid for the player
    }

    void OnPostprocessMaterial(Material m)
    {
        if (!IsBasement) return;
        Setup(m);
    }

    public static void Setup(Material m)
    {
        var lit = Shader.Find("Universal Render Pipeline/Lit");
        if (lit != null && m.shader != lit) m.shader = lit;
        string n = m.name;

        if (n.StartsWith("M_Water")) { Transparent(m, new Color(0.012f, 0.018f, 0.012f, 0.85f), 0.95f); return; }
        if (n.StartsWith("M_Glass")) { Transparent(m, new Color(0.55f, 0.6f, 0.58f, 0.2f), 0.95f); return; }
        if (!n.StartsWith("M_")) return;

        string g = n.Substring(2);
        var albedo = Load(g, "Albedo");
        var normal = Load(g, "Normal");
        var metalSmooth = Load(g, "MetalSmooth");
        var emission = Load(g, "Emission");

        if (albedo != null) { m.SetTexture("_BaseMap", albedo); m.SetColor("_BaseColor", Color.white); }
        if (normal != null) { m.SetTexture("_BumpMap", normal); m.SetFloat("_BumpScale", 1f); m.EnableKeyword("_NORMALMAP"); }
        if (metalSmooth != null)
        {
            m.SetFloat("_WorkflowMode", 1f);
            m.SetTexture("_MetallicGlossMap", metalSmooth);
            m.SetFloat("_Smoothness", 1f);
            m.SetFloat("_SmoothnessTextureChannel", 0f); // smoothness from MetalSmooth alpha
            m.EnableKeyword("_METALLICSPECGLOSSMAP");
        }
        if (emission != null)
        {
            float gain = EmissionGain.TryGetValue(g, out var v) ? v : 3f;
            m.SetTexture("_EmissionMap", emission);
            m.SetColor("_EmissionColor", Color.white * gain);
            m.EnableKeyword("_EMISSION");
            m.globalIlluminationFlags = MaterialGlobalIlluminationFlags.BakedEmissive;
        }
    }

    static void Transparent(Material m, Color c, float smoothness)
    {
        m.SetFloat("_Surface", 1f);
        m.SetFloat("_Blend", 0f);
        m.SetFloat("_SrcBlend", (float)BlendMode.SrcAlpha);
        m.SetFloat("_DstBlend", (float)BlendMode.OneMinusSrcAlpha);
        m.SetFloat("_SrcBlendAlpha", (float)BlendMode.One);
        m.SetFloat("_DstBlendAlpha", (float)BlendMode.OneMinusSrcAlpha);
        m.SetFloat("_ZWrite", 0f);
        m.SetOverrideTag("RenderType", "Transparent");
        m.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");
        m.renderQueue = (int)RenderQueue.Transparent;
        m.SetColor("_BaseColor", c);
        m.SetFloat("_Smoothness", smoothness);
    }

    static Texture2D Load(string group, string kind) =>
        AssetDatabase.LoadAssetAtPath<Texture2D>($"{TexDir}T_{group}_{kind}.png");

    [MenuItem("Tools/Can You Hear Me/Reimport Basement")]
    static void Reimport()
    {
        AssetDatabase.ImportAsset(TexDir.TrimEnd('/'), ImportAssetOptions.ImportRecursive | ImportAssetOptions.ForceUpdate);
        AssetDatabase.ImportAsset(FbxPath, ImportAssetOptions.ForceUpdate);
        Debug.Log("Basement reimported with baked URP materials.");
    }

    // Ensures URP/Lit is in Always Included Shaders so Shader.Find() and all runtime-created
    // materials (transparent, alpha-clip, emission variants) survive build-time shader stripping.
    [InitializeOnLoadMethod]
    static void EnsureUrpLitAlwaysIncluded()
    {
        EditorApplication.delayCall += () =>
        {
            var gs = AssetDatabase.LoadAssetAtPath<UnityEngine.Object>("ProjectSettings/GraphicsSettings.asset");
            if (gs == null) return;
            var so = new SerializedObject(gs);
            var arr = so.FindProperty("m_AlwaysIncludedShaders");
            if (arr == null) return;
            var sh = Shader.Find("Universal Render Pipeline/Lit");
            if (sh == null) return;
            for (int i = 0; i < arr.arraySize; i++)
                if (arr.GetArrayElementAtIndex(i).objectReferenceValue == sh) return;
            arr.InsertArrayElementAtIndex(arr.arraySize);
            arr.GetArrayElementAtIndex(arr.arraySize - 1).objectReferenceValue = sh;
            so.ApplyModifiedProperties();
            AssetDatabase.SaveAssets();
            Debug.Log("[BasementSceneImporter] URP/Lit added to Always Included Shaders for build safety.");
        };
    }
}
